import networkx as nx
G = nx.Graph()
for i in range(21):
    G.add_node(i)
for i in range(21):
    for j in range(i+1, 21):
        if len(list(G.neighbors(i))) < 5 and len(list(G.neighbors(j))) < 5:
            G.add_edge(i, j)
            if len(list(G.neighbors(i))) == 5 or len(list(G.neighbors(j))) == 5:
                break
if min(list(G.degree())) < 3 or max(list(G.degree())) > 5:
    print("UNSATISFIABLE")
else:
    print(list(G.edges()))
